/**
 * SubSafe Example - Direct Mode
 * 
 * This example demonstrates using SubSafe with Direct mode:
 * - Creating a server using environment configuration
 * - Subscribing to a topic
 * - Listening for and processing notifications with credential in the message body
 * 
 * To run this example:
 * 1. Set up environment variables (see .env.example)
 * 2. Run with: node examples/direct-mode.js
 */

// Load environment variables
require('dotenv').config();
const path = require('path');
const fs = require('fs');

// Import the SubSafe module
const SubSafe = require('../src/index');
const logger = require('../src/services/logger');

// Set log level from environment or use default
logger.level = process.env.LOG_LEVEL || 'info';

// Set direct mode explicitly
process.env.DATA_SOURCE_MODE = 'direct';
logger.info('Using DATA_SOURCE_MODE=direct');

// Make sure we have temp files for encrypted and decrypted content
const tempEncryptedFile = process.env.TEMP_ENCRYPTED_FILE || path.resolve(__dirname, '../temp-encrypted.txt');
const tempDecryptedFile = process.env.TEMP_DECRYPTED_FILE || path.resolve(__dirname, '../temp-decrypted.txt');

logger.info('Temp encrypted file path:', tempEncryptedFile);
logger.info('Temp decrypted file path:', tempDecryptedFile);

// Ensure directories exist
fs.mkdirSync(path.dirname(tempEncryptedFile), { recursive: true });
fs.mkdirSync(path.dirname(tempDecryptedFile), { recursive: true });

// Create empty files if they don't exist
if (!fs.existsSync(tempEncryptedFile)) {
  logger.info(`Creating empty file: ${tempEncryptedFile}`);
  fs.writeFileSync(tempEncryptedFile, '');
}

if (!fs.existsSync(tempDecryptedFile)) {
  logger.info(`Creating empty file: ${tempDecryptedFile}`);
  fs.writeFileSync(tempDecryptedFile, '');
}

// Verify critical environment variables
const requiredVars = [
  'MOSIP_WEBSUB_URL',
  'MOSIP_TOPIC',
  'MOSIP_WEBSUB_SECRET',
  'MOSIP_BASE_URL',
  'MOSIP_CLIENT_ID',
  'MOSIP_SECRET_KEY',
  'MOSIP_TOKEN_URL',
  'P12_PATH',
  'DIRECT_MESSAGE_PATH'
];

const missingVars = requiredVars.filter(name => !process.env[name]);
if (missingVars.length > 0) {
  logger.error(`Missing required environment variables: ${missingVars.join(', ')}`);
  process.exit(1);
}

// Create a SubSafe instance with configuration from environment
const subsafe = new SubSafe({
  // Server configuration 
  port: process.env.PORT || 3002,
  
  // Log level configuration
  logLevel: process.env.LOG_LEVEL || 'info',
  
  // WebSub configuration
  hubUrl: process.env.MOSIP_WEBSUB_URL,
  topic: process.env.MOSIP_TOPIC,
  callbackPath: process.env.CALLBACK_PATH || '/callback/notifyEvent',
  secret: process.env.MOSIP_WEBSUB_SECRET,
  
  // Data source configuration - explicitly set to direct mode
  dataSourceMode: 'direct',
  directMessagePath: process.env.DIRECT_MESSAGE_PATH,
  
  // Auth configuration
  baseUrl: process.env.MOSIP_BASE_URL,
  clientId: process.env.MOSIP_CLIENT_ID,
  clientSecret: process.env.MOSIP_SECRET_KEY,
  tokenUrl: process.env.MOSIP_TOKEN_URL,
  authEndpoint: process.env.MOSIP_AUTH_ENDPOINT,
  appId: process.env.MOSIP_APP_ID,
  
  // Decryption configuration
  p12Path: process.env.P12_PATH,
  p12Password: process.env.P12_PASSWORD,
  tempEncryptedFile: process.env.TEMP_ENCRYPTED_FILE || tempEncryptedFile,
  tempDecryptedFile: process.env.TEMP_DECRYPTED_FILE || tempDecryptedFile
});

// Register notification handler for incoming messages
subsafe.onNotification((data, rawEvent) => {
  logger.info('Event received - Direct Mode');
  
  if (data && data.error) {
    logger.error('Error in decryption:', { error: data.error });
    return;
  }
  
  logger.info('Message successfully received and decrypted');
  logger.debug('Decrypted data:', { data });
  
  // Add your business logic here
  // For example:
  if (data && data.registrationId) {
    logger.info(`Processing registration ID: ${data.registrationId}`);
    // Process the data...
  }
});

// Extract callback URL from environment
const callbackUrl = process.env.CALLBACK_URL;
logger.info(`Using callback URL: ${callbackUrl}`);

// Log configuration for verification
logger.info('Configuration:');
logger.info('Data Source Mode: Direct');
logger.info(`Direct Message Path: ${process.env.DIRECT_MESSAGE_PATH}`);
logger.info(`WebSub URL: ${process.env.MOSIP_WEBSUB_URL}`);
logger.info(`Topic: ${process.env.MOSIP_TOPIC}`);
logger.info(`Callback Path: ${process.env.CALLBACK_PATH || '/callback/notifyEvent'}`);
logger.info(`Log Level: ${process.env.LOG_LEVEL || 'info'}`);

// Start server and subscribe
subsafe.start(callbackUrl)
  .then(async (server) => {
    logger.info('Server started successfully');
    logger.info(`Using callback URL: ${subsafe.callbackUrl}`);
    
    try {
      logger.info('Subscribing to topic...');
      await subsafe.subscribe();
      logger.info('Subscription successful');
      logger.info('Waiting for notifications with credential in message body... Press Ctrl+C to exit');
      
      // Log sample expected format
      logger.info('Expecting notifications with format:');
      logger.debug('Example notification format:', {
        publisher: "CREDENTIAL_SERVICE",
        topic: "patner-opencrvs-i1/CREDENTIAL_ISSUED",
        publishedOn: "2025-03-28T11:33:26.355Z",
        event: {
          id: "1a61e56f-70c5-4369-9cb4-e602f0af328d",
          transactionId: "adb5f231-cb59-487a-8895-dac71d584927",
          type: {
            namespace: "mosip",
            name: "mosip:idp:credential:issued"
          },
          timestamp: "2025-03-28T11:33:26.355Z",
          data: {
            credential: "encrypted-credential-data-here",
            registrationId: "10001100770000320240329061813"
          }
        }
      });
    } catch (error) {
      logger.error('Error during subscription:', error);
    }
  })
  .catch(error => {
    logger.error('Server start error:', error);
  }); 